'use client'

import { useState } from 'react'
import { Lock } from 'lucide-react'
import { api, ApiError } from '@/lib/api'

export function PremiumGate() {
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const handleUpgrade = async () => {
    setIsLoading(true)
    setError(null)
    try {
      const result = await api.payments.initialize()
      window.location.href = result.authorizationUrl
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err.detail)
      } else {
        setError('Could not start payment. Please try again.')
      }
      setIsLoading(false)
    }
  }

  return (
    <div className="bg-white rounded-xl border border-slate-200 p-6">
      <div className="flex flex-col items-center text-center py-6">
        <div className="h-12 w-12 rounded-full bg-primary-50 flex items-center justify-center mb-4">
          <Lock className="h-6 w-6 text-primary" />
        </div>
        <h2 className="text-lg font-semibold text-slate-900 mb-2">
          Unlock your full rewrite
        </h2>
        <p className="text-sm text-slate-500 max-w-sm mb-6">
          Get your headline, about section, experience bullets, skills, banner concept, and quick tips — all rewritten by AI and ready to copy.
        </p>

        {error && (
          <p className="text-sm text-red-600 mb-4">{error}</p>
        )}

        <button
          onClick={handleUpgrade}
          disabled={isLoading}
          className="bg-primary text-white px-8 py-3 rounded-lg font-medium text-sm hover:bg-primary-600 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {isLoading ? 'Redirecting to payment…' : 'Get the full rewrite'}
        </button>
      </div>
    </div>
  )
}
